    },
    {
      "fact_text": {
        "text": "The ceiling method returns the smallest integer that is greater than or equal to the given number.",
        "refs": ["Q0006", "Q0007"],
        "claims": [
          {
            "text": "Ceiling returns the smallest integer ≥ the input number.",
